package server

import (
	"context"
	"time"

	"github.com/gofrs/uuid"
	"github.com/golang/protobuf/ptypes/empty"
	flipt "github.com/markphelps/flipt/rpc"
)

// GetRule gets a rule
func (s *Server) GetRule(ctx context.Context, req *flipt.GetRuleRequest) (*flipt.Rule, error) {
	return s.RuleStore.GetRule(ctx, req)
}

// ListRules lists all rules
func (s *Server) ListRules(ctx context.Context, req *flipt.ListRuleRequest) (*flipt.RuleList, error) {
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}

	rules, err := s.RuleStore.ListRules(ctx, req)
	if err != nil {
		return nil, err
	}

	var resp flipt.RuleList

	for i := range rules {
		resp.Rules = append(resp.Rules, rules[i])
	}

	return &resp, nil
}

// CreateRule creates a rule
func (s *Server) CreateRule(ctx context.Context, req *flipt.CreateRuleRequest) (*flipt.Rule, error) {
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if req.SegmentKey == "" {
		return nil, emptyFieldError("segmentKey")
	}
	if req.Rank <= 0 {
		return nil, invalidFieldError("rank", "must be greater than 0")
	}
	return s.RuleStore.CreateRule(ctx, req)
}

// UpdateRule updates an existing rule
func (s *Server) UpdateRule(ctx context.Context, req *flipt.UpdateRuleRequest) (*flipt.Rule, error) {
	if req.Id == "" {
		return nil, emptyFieldError("id")
	}
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if req.SegmentKey == "" {
		return nil, emptyFieldError("segmentKey")
	}
	return s.RuleStore.UpdateRule(ctx, req)
}

// DeleteRule deletes a rule
func (s *Server) DeleteRule(ctx context.Context, req *flipt.DeleteRuleRequest) (*empty.Empty, error) {
	if req.Id == "" {
		return nil, emptyFieldError("id")
	}
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}

	if err := s.RuleStore.DeleteRule(ctx, req); err != nil {
		return nil, err
	}

	return &empty.Empty{}, nil
}

// OrderRules orders rules
func (s *Server) OrderRules(ctx context.Context, req *flipt.OrderRulesRequest) (*empty.Empty, error) {
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if len(req.RuleIds) < 2 {
		return nil, invalidFieldError("ruleIds", "must contain atleast 2 elements")
	}

	if err := s.RuleStore.OrderRules(ctx, req); err != nil {
		return nil, err
	}

	return &empty.Empty{}, nil
}

// CreateDistribution creates a distribution
func (s *Server) CreateDistribution(ctx context.Context, req *flipt.CreateDistributionRequest) (*flipt.Distribution, error) {
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if req.RuleId == "" {
		return nil, emptyFieldError("ruleId")
	}
	if req.VariantId == "" {
		return nil, emptyFieldError("variantId")
	}
	if req.Rollout < 0 {
		return nil, invalidFieldError("rollout", "must be greater than or equal to '0'")
	}
	if req.Rollout > 100 {
		return nil, invalidFieldError("rollout", "must be less than or equal to '100'")
	}
	return s.RuleStore.CreateDistribution(ctx, req)
}

// UpdateDistribution updates an existing distribution
func (s *Server) UpdateDistribution(ctx context.Context, req *flipt.UpdateDistributionRequest) (*flipt.Distribution, error) {
	if req.Id == "" {
		return nil, emptyFieldError("id")
	}
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if req.RuleId == "" {
		return nil, emptyFieldError("ruleId")
	}
	if req.VariantId == "" {
		return nil, emptyFieldError("variantId")
	}
	if req.Rollout < 0 {
		return nil, invalidFieldError("rollout", "must be greater than or equal to '0'")
	}
	if req.Rollout > 100 {
		return nil, invalidFieldError("rollout", "must be less than or equal to '100'")
	}
	return s.RuleStore.UpdateDistribution(ctx, req)
}

// DeleteDistribution deletes a distribution
func (s *Server) DeleteDistribution(ctx context.Context, req *flipt.DeleteDistributionRequest) (*empty.Empty, error) {
	if req.Id == "" {
		return nil, emptyFieldError("id")
	}
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if req.RuleId == "" {
		return nil, emptyFieldError("ruleId")
	}
	if req.VariantId == "" {
		return nil, emptyFieldError("variantId")
	}

	if err := s.RuleStore.DeleteDistribution(ctx, req); err != nil {
		return nil, err
	}

	return &empty.Empty{}, nil
}

// Evaluate evaluates a request for a given flag and entity
func (s *Server) Evaluate(ctx context.Context, req *flipt.EvaluationRequest) (*flipt.EvaluationResponse, error) {
	if req.FlagKey == "" {
		return nil, emptyFieldError("flagKey")
	}
	if req.EntityId == "" {
		return nil, emptyFieldError("entityId")
	}

	startTime := time.Now()

	// set request ID if not present
	if req.RequestId == "" {
		req.RequestId = uuid.Must(uuid.NewV4()).String()
	}

	resp, err := s.RuleStore.Evaluate(ctx, req)
	if err != nil {
		return nil, err
	}

	if resp != nil {
		resp.RequestDurationMillis = float64(time.Since(startTime)) / float64(time.Millisecond)
	}

	return resp, nil
}

package server

import (
	"context"
	"database/sql"

	pb "github.com/markphelps/flipt/rpc"
	"github.com/markphelps/flipt/storage"
	"github.com/markphelps/flipt/storage/cache"

	sq "github.com/Masterminds/squirrel"
	"github.com/sirupsen/logrus"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

var _ pb.FliptServer = &Server{}

// Server serves the Flipt backend
type Server struct {
	logger logrus.FieldLogger
	cache  cache.Cacher

	storage.FlagStore
	storage.SegmentStore
	storage.RuleStore
}

// New creates a new Server
func New(logger logrus.FieldLogger, builder sq.StatementBuilderType, db *sql.DB, opts ...Option) *Server {
	var (
		flagStore    = storage.NewFlagStorage(logger, builder)
		segmentStore = storage.NewSegmentStorage(logger, builder)
		ruleStore    = storage.NewRuleStorage(logger, builder, db)

		s = &Server{
			logger:       logger,
			FlagStore:    flagStore,
			SegmentStore: segmentStore,
			RuleStore:    ruleStore,
		}
	)

	for _, opt := range opts {
		opt(s)
	}

	if s.cache != nil {
		// wrap flagStore with lru cache
		s.FlagStore = cache.NewFlagCache(logger, s.cache, flagStore)
	}

	return s
}

// ErrorUnaryInterceptor intercepts known errors and returns the appropriate GRPC status code
func (s *Server) ErrorUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	resp, err = handler(ctx, req)
	if err == nil {
		return
	}

	errorsTotal.Inc()

	switch err.(type) {
	case storage.ErrNotFound:
		err = status.Error(codes.NotFound, err.Error())
	case storage.ErrInvalid:
		err = status.Error(codes.InvalidArgument, err.Error())
	case errInvalidField:
		err = status.Error(codes.InvalidArgument, err.Error())
	default:
		err = status.Error(codes.Internal, err.Error())
	}
	return
}

package storage

import (
	"database/sql"
	"database/sql/driver"
	"fmt"
	"net/url"
	"time"

	"github.com/golang/protobuf/ptypes"
	proto "github.com/golang/protobuf/ptypes/timestamp"
	"github.com/pkg/errors"
)

type timestamp struct {
	*proto.Timestamp
}

func (t *timestamp) Scan(value interface{}) error {
	v, ok := value.(time.Time)
	if ok {
		val, err := ptypes.TimestampProto(v)
		if err != nil {
			return err
		}
		t.Timestamp = val
	}
	return nil
}

func (t *timestamp) Value() (driver.Value, error) {
	return ptypes.Timestamp(t.Timestamp)
}

const (
	pgConstraintForeignKey = "foreign_key_violation"
	pgConstraintUnique     = "unique_violation"
)

// Open opens a connection to the db given a URL
func Open(url string) (*sql.DB, Driver, error) {
	driver, u, err := parse(url)
	if err != nil {
		return nil, 0, err
	}

	db, err := sql.Open(driver.String(), u.String())
	if err != nil {
		return nil, 0, err
	}

	return db, driver, nil
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
	}

	schemeToDriver = map[string]Driver{
		"file":     SQLite,
		"postgres": Postgres,
	}
)

// Driver represents a database driver type
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
)

func parse(in string) (Driver, *url.URL, error) {
	u, err := url.Parse(in)
	if err != nil {
		return 0, u, errors.Wrapf(err, "parsing url: %q", in)
	}

	driver := schemeToDriver[u.Scheme]
	if driver == 0 {
		return 0, u, fmt.Errorf("unknown database driver for: %s", u.Scheme)
	}

	if driver == SQLite {
		v := u.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		u.RawQuery = v.Encode()
	}

	return driver, u, nil
}

