			},
			rules: &flipt.RuleList{
				Rules: []*flipt.Rule{
					{
						FlagKey: "flagKey",
					},
				},
			},
		},
		{
			name: "emptyFlagKey",
			req:  &flipt.ListRuleRequest{FlagKey: ""},
			f: func(ctx context.Context, r *flipt.ListRuleRequest) ([]*flipt.Rule, error) {
				assert.NotNil(t, r)
