			wantErr: errors.New("error test"),
		},
	}

	for _, tt := range tests {
		var (
			f       = tt.f
			req     = tt.req
			rules   = tt.rules
			wantErr = tt.wantErr
		)

		t.Run(tt.name, func(t *testing.T) {
			s := &Server{
				RuleStore: &ruleStoreMock{
					listRulesFn: f,
				},
			}

			got, err := s.ListRules(context.TODO(), req)
			assert.Equal(t, wantErr, err)
			assert.Equal(t, rules, got)
		})
	}
}

